import {mountExperiment} from './experiment-ui.js';
import {majority,queueModel,tailProbability,quorum,placement,shardLoads,retrySchedule,bucketStep,burnRate,estimate,vectorRelation,applyDelivery,recovery} from './systems-models.js';
const R=(key,label,min,max,step=1)=>({kind:'range',key,label,min,max,step});
const C=(key,label,options)=>({kind:'choice',key,label,options});
const T=(key,label)=>({kind:'toggle',key,label});
const B=(key,label)=>({kind:'button',key,label});
const fmt=(x,d=0)=>Number.isFinite(x)?x.toLocaleString('en',{maximumFractionDigits:d}):'Unbounded';
const stat=(label,value)=>`<div class="stat"><strong>${value}</strong><small>${label}</small></div>`;
const stats=(...xs)=>`<div class="ds-stats">${xs.map(([l,v])=>stat(l,v)).join('')}</div>`;
const note=(text,warn=false)=>`<div class="insight ${warn?'ds-warning':''}" role="status">${text}</div>`;
const box=(label,value,color='green')=>`<div class="node ${color}"><small>${label}</small><div class="ds-node-value">${value}</div></div>`;
const flow=items=>`<div class="ds-flow">${items.map((x,i)=>`${i?'<span class="op" aria-hidden="true">→</span>':''}${typeof x==='string'?box('',x):box(...x)}`).join('')}</div>`;
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const bars=(labels,values,max=Math.max(...values),colors=[])=>`<div class="ds-bars-scroll"><div class="ds-bars" style="min-width:${labels.length>8?labels.length*34:0}px" role="img" aria-label="${labels.map((l,i)=>`${l}: ${fmt(values[i],1)}`).join('; ')}">${labels.map((l,i)=>`<div class="ds-bar-column"><span class="mono">${fmt(values[i],1)}</span><div class="ds-bar-space"><i style="height:${Math.max(1,values[i]/Math.max(1,max)*100)}%;background:${colors[i]||'var(--green)'}"></i></div><small>${l}</small></div>`).join('')}</div></div>`;
const timeline=(rows,max=500)=>`<div class="ds-trace">${rows.map(([name,start,duration,color])=>`<div class="ds-trace-row"><span>${name}</span><div class="ds-trace-track"><i style="left:${start/max*100}%;width:${Math.max(1,duration/max*100)}%;background:${color||'var(--green)'}">${duration} ms</i></div></div>`).join('')}</div>`;
const chips=xs=>`<div class="ds-packets">${xs.map(x=>`<span class="token">${x}</span>`).join('')}</div>`;
const labs={};

labs.request=()=>({title:'Follow the request',state:{latency:40,fanout:10,failure:'None'},controls:[R('latency','Slow dependency (ms)',10,400,10),R('fanout','Parallel leaves',1,100),C('failure','Failure point',['None','Before write','Reply lost'])],render:s=>{
 const total=35+s.latency;
 return flow([['Client','request','blue'],['Edge','DNS · TLS · LB',''],['Service',`${s.fanout} calls`],['Database',s.failure==='Before write'?'no write':'write applied','purple']])+timeline([['Network',0,15],['Service',15,20],['Critical leaf',35,s.latency,'var(--blue)']],440)+stats(['Critical path',`${total} ms`],['At least one slow leaf',`${(tailProbability(.01,s.fanout)*100).toFixed(1)}%`],['Client result',s.failure==='None'?'Success':'Timeout'])+note(s.failure==='Reply lost'?'The database applied the write; its response disappeared. The caller sees a timeout, not proof of failure.':s.failure==='Before write'?'This time the write never happened. From the caller’s timeout alone, this case looks like a lost reply.':'Parallel latency follows the slowest required dependency, not the sum. Serial work still adds to the critical path.');},foot:'Latency example is illustrative. Each independent leaf has an assumed 1% slow-response probability.'});

labs.queues=()=>({title:'Move toward saturation',state:{arrival:70,capacity:100},controls:[R('arrival','Arrivals / second',5,150,5),R('capacity','Service capacity / second',50,200,5)],render:s=>{
 const q=queueModel(s.arrival,s.capacity);const points=Array.from({length:99},(_,i)=>`${35+(i+1)/100*630},${210-Math.min(190,2/(1-(i+1)/100))}`).join(' ');
 return `<div class="ds-plot"><svg viewBox="0 0 700 240" role="img" aria-label="Queueing delay rises sharply as utilization approaches one"><path d="M35 15V210H670" stroke="#556050" fill="none"/><polyline points="${points}" fill="none" stroke="#c5f277" stroke-width="3"/><line x1="${35+Math.min(.99,q.rho)*630}" y1="15" x2="${35+Math.min(.99,q.rho)*630}" y2="210" stroke="#92c9ec" stroke-dasharray="5 5"/><text x="40" y="235">0% utilization</text><text x="540" y="235">100% →</text><text x="55" y="35">Mean response time grows</text></svg></div>`+stats(['Utilization',`${fmt(q.rho*100)}%`],['Mean response time',q.stable?`${fmt(q.time*1000,1)} ms`:'Unbounded'],['Mean in flight',q.stable?fmt(q.inflight,1):'Growing'])+note(q.stable?'Try 95% utilization, then cross 100%. Small capacity changes near saturation have large effects.':'No steady state exists with this unbounded queue at these rates. Limit admissions or increase sustainable capacity.',!q.stable);},foot:'M/M/1 queue, idealized stochastic steady state. The curve is conceptual; statistics use λ and μ.'});

labs.clocks=()=>({title:'Separate time from causality',state:{skew:-35,view:'Wall time'},controls:[R('skew','Node B clock offset (ms)',-80,80,5),C('view','Clock',['Wall time','Lamport','Vector'])],render:s=>{
 const clock=s.view==='Wall time'?['20 ms',`${40+s.skew} ms`]:s.view==='Lamport'?['2','3']:['[2, 0]','[2, 1]'];
 return flow([['Node A · sends',clock[0]],['Network','20 ms transit',''],['Node B · receives',clock[1],'blue']])+stats(['Real send time','20 ms'],['Real receive time','40 ms'],['Wall-clock order',40+s.skew<20?'Reversed':'Not reversed'])+note(s.view==='Wall time'?'Move B’s clock backward. A receive can look earlier than its cause even though the network delay is positive.':s.view==='Lamport'?'Receive clock = max(local, message) + 1. This preserves causal order without relying on synchronized physical clocks.':'The receive vector dominates the send vector. Independent [2,0] and [0,2] would instead be concurrent.');},foot:'One message between two processes. Logical/vector examples are fixed; physical skew is adjustable.'});

labs.partitions=()=>({title:'Read through a partition',state:{split:true,policy:'Protect order',written:false,replica:0},controls:[T('split','Link partitioned'),C('policy','Read policy',['Protect order','Serve local']),B('write','Write x = 1 in region A')],actions:{write:s=>{s.written=true;if(!s.split)s.replica=1;}},onChange:s=>{if(!s.split&&s.written)s.replica=1;},render:s=>{
 const a=s.written?1:0,b=s.replica,blocked=s.split&&s.policy==='Protect order';
 return flow([['Region A · authority',`x = ${a}`],['Link',s.split?'PARTITION':'connected',s.split?'purple':''],['Region B · read',blocked?'unavailable':`x = ${b}`,'blue']])+stats(['A’s write',s.written?'Completed':'Not sent'],['B’s response',blocked?'Blocked':'Served'],['Latest value visible',blocked?'No response':a===b?'Yes':'No'])+note(blocked?'B refuses a potentially stale read because it cannot validate the authority. Some clients lose availability.':s.split&&s.written?'B responds with x = 0 after A’s write completed. That history violates a linearizable read contract.':'Write in A, then disconnect the regions and compare the two read policies.');},foot:'Single-key read scenario with a fixed authority; not a complete replication or failover protocol.'});

labs.consistency=()=>({title:'Read from a lagging follower',state:{lag:4,elapsed:1,policy:'Any replica'},controls:[R('lag','Replication delay (seconds)',0,10),R('elapsed','Read after write (seconds)',0,10),C('policy','Read route',['Any replica','Read-your-writes','Leader'])],render:s=>{
 const stale=s.elapsed<s.lag,wait=s.policy==='Read-your-writes'&&stale?s.lag-s.elapsed:0,value=stale&&s.policy==='Any replica'?'v1':'v2';
 return flow([['Writer','v2 acknowledged'],['Leader','v2','purple'],['Follower',stale?'v1':'v2','blue']])+stats(['Read result',value],['Additional wait',`${wait} s`],['Destination',s.policy==='Leader'?'Leader':'Follower'])+note(value==='v1'?'The writer reads its own old profile. Eventual replication can converge later but has not met a session guarantee now.':wait?`The session requires v2, so this follower waits ${wait} seconds. Alternatively, route to an authoritative up-to-date node.`:'This simplified route returns v2. A real leader read still needs valid leadership and the correct read barrier.');},foot:'Single completed write and fixed replication delay. No concurrent updates or leader change.'});

labs.quorums=()=>({title:'Make replica sets intersect',state:{r:2,w:3,down:0},controls:[R('r','Read acknowledgments R',1,5),R('w','Write acknowledgments W',1,5),R('down','Unavailable replicas',0,4)],render:s=>{
 const q=quorum(5,s.r,s.w);return `<div class="ds-replicas">${Array.from({length:5},(_,i)=>box(`Replica ${i+1}`,`${i<s.w?'W ':''}${i>=5-s.r?'R':''}${i<s.down?' · offline':''}`,i<s.down?'':i<s.w&&i>=5-s.r?'purple':i<s.w?'green':'blue')).join('')}</div>`+stats(['R + W versus N',`${s.r+s.w} / 5`],['Guaranteed intersection',q.overlap?'Yes':'No'],['Can complete both?',5-s.down>=Math.max(s.r,s.w)?'Yes':'No'])+note(q.overlap?'Every read set intersects every completed write set in this fixed membership. Version selection and concurrent writes still need a protocol.':'The pictured sets can avoid each other. A read may see only replicas that missed the completed write.',!q.overlap);},foot:'N = 5. Pictured read/write sets maximize separation; offline markers illustrate quorum availability independently.'});

labs.consensus=()=>({title:'A leader needs a majority',state:{reachable:3,term:7,appended:false,committed:false,fenced:true,electionBlocked:false},controls:[R('reachable','Reachable replicas, including leader',1,5),T('fenced','Enforce fencing at storage'),B('append','Propose current-term entry'),B('term','Attempt next-term election')],actions:{append:s=>{s.appended=true;s.electionBlocked=false;if(s.reachable>=majority(5))s.committed=true;},term:s=>{s.electionBlocked=s.reachable<majority(5);if(!s.electionBlocked){s.term++;s.appended=false;s.committed=false;}}},onChange:s=>{if(s.appended&&s.reachable>=3)s.committed=true;},render:s=>{
 const committed=s.committed;return `<div class="ds-replicas">${Array.from({length:5},(_,i)=>box(i===0?`Leader · term ${s.term}`:`Follower ${i}`,i>=s.reachable?'unreachable':s.appended?(committed?'entry committed':'entry pending'):'log prefix',i>=s.reachable?'':i===0?'purple':'green')).join('')}</div>`+stats(['Required majority','3 / 5'],['Proposed entry',committed?'Committed':s.appended?'Pending':'Not proposed'],['Old-term writer',s.fenced?'Rejected':'Unsafe'])+note(s.electionBlocked?'No new leader is elected in this toy attempt: a majority of votes is unavailable. A real candidate may increment its own term without winning leadership.':!s.fenced?'A paused owner can act after losing leadership unless the resource enforces fencing. A local belief in leadership is not authority.':committed?'This current-term entry reached a durable majority in the toy model. The state machine can now apply the committed prefix.':'Try a proposal with only two reachable replicas, then restore connectivity. An append is not yet a committed result.',!s.fenced);},foot:'Current-term illustration; all reachable voters are assumed up to date. Full elections, log repair, and reconfiguration are omitted.'});

labs.conflicts=()=>({title:'Resolve concurrent updates',state:{clock:20,merge:'Last-write-wins',a:2,b:3},controls:[R('clock','A clock offset',-50,50,5),C('merge','Data / merge',['Last-write-wins','Keep siblings','G-counter']),B('incA','Increment at A'),B('incB','Increment at B')],actions:{incA:s=>s.a++,incB:s=>s.b++},render:s=>{
 const va=[s.a,0],vb=[0,s.b],winner=100+s.clock>=110?'A: blue':'B: green';return flow([['Replica A',s.merge==='G-counter'?`[${s.a}, 0]`:'color = blue'],['Merge',s.merge==='G-counter'?`[${s.a}, ${s.b}]`:s.merge==='Keep siblings'?'both versions':winner,'purple'],['Replica B',s.merge==='G-counter'?`[0, ${s.b}]`:'color = green','blue']])+stats(['Vector relationship',vectorRelation(va,vb)],['Merged counter',s.a+s.b],['A / B wall times',`${100+s.clock} / 110`])+note(s.merge==='G-counter'?'Per-replica components merge with max, then sum. Merging the same state twice does not count the increments twice.':s.merge==='Keep siblings'?'Preserve both concurrent values; the application must reconcile what they mean.':'Move A’s clock. Timestamp arbitration can change the winner without changing either user’s intention.');},foot:'Counter increments are owned by distinct replica IDs. The color register uses a separate illustrative timestamp policy.'});

labs.durability=()=>({title:'Crash between durability milestones',state:{stage:0,crashed:false},controls:[B('step','Advance write'),B('crash','Crash process')],actions:{step:s=>{s.stage=Math.min(4,s.stage+1);s.crashed=false;},crash:s=>s.crashed=true},render:s=>{
 const labels=['Volatile buffer','WAL synced','Replica synced','Data page flushed','Client acknowledged'];return flow(labels.map((l,i)=>[l,i<=s.stage?'completed':'pending',i<=s.stage?'green':'']))+stats(['Survives local process crash',s.stage>=1?'Yes':'No'],['Survives loss of this disk',s.stage>=2?'On replica':'No'],['Client has success',s.stage>=4?'Yes':'No'])+note(s.crashed?(s.stage>=1?'Recovery can replay the durable WAL prefix. This model assumes a correct sync and intact local storage.':'The buffered write is lost. No durable copy exists at this stage.'):'Advance the write, then inject a crash. This policy waits for a durable replica before acknowledgment.',s.crashed&&s.stage===0);},foot:'Illustrative synchronous replication policy. Durability depends on storage, sync settings, and independent failure domains.'});

labs.isolation=()=>({title:'Two doctors, one invariant',state:{step:0,level:'Snapshot'},controls:[C('level','Isolation',['Snapshot','Serializable']),B('step','Advance concurrent schedule')],actions:{step:s=>s.step=Math.min(4,s.step+1)},render:s=>{
 const a=s.step<3,b=s.step<4||s.level==='Serializable';return flow([['Transaction A',s.step>=1?'saw B on call':'not read','blue'],['Invariant','at least one doctor',''],['Transaction B',s.step>=2?'saw A on call':'not read','purple']])+table(['Step','A','B'],[['1','Reads B = on',''],['2','','Reads A = on'],['3',s.step>=3?'Commits A = off':'pending',''],['4','',s.step>=4?(s.level==='Serializable'?'Aborted: retry required':'Commits B = off'):'pending']])+stats(['A on call',a?'Yes':'No'],['B on call',b?'Yes':'No'],['Invariant',a||b?'Preserved':'VIOLATED'])+note(s.step<4?'Both transactions read a valid snapshot, then write different rows. Step through both commits.':s.level==='Serializable'?'One transaction must not commit this non-serializable schedule. A real engine may block or abort; this lab aborts B.':'Both individual decisions looked safe, but their combination left nobody on call.',s.step===4&&s.level==='Snapshot');},foot:'Write skew under snapshot isolation. Real serializable engines may prevent the schedule differently.'});

labs.atomicity=()=>({title:'Break a multi-service purchase',state:{mode:'Two-phase commit',stage:0,failed:false},controls:[C('mode','Protocol',['Two-phase commit','Saga']),B('step','Advance'),B('fail','Lose coordinator / fail payment')],actions:{step:s=>{s.stage=Math.min(3,s.stage+1);s.failed=false;},fail:s=>s.failed=true},render:s=>{
 const two=s.mode==='Two-phase commit';const labels=two?['Begin','Prepare durable intents','Commit decision','Apply commit']:['Begin','Reserve inventory','Authorize payment','Schedule shipping'];return flow([['Coordinator / workflow',labels[s.stage],'purple'],['Inventory',s.failed?(two&&s.stage===1?'prepared · blocked':!two&&s.stage>=1?'release reservation':'inspect durable decision'):s.stage>=1?'reserved / prepared':'unchanged'],['Payment',s.failed?'outcome needs resolution':s.stage>=2?'authorized / commit':'pending','blue']])+note(s.failed?(two?'A prepared participant cannot invent the missing decision. Recover the durable coordinator record before resolving its prepared state.':'A saga persists progress and runs a compensating action after resolving uncertain payment state. Compensation itself can fail.'):'Advance once, then inject failure. Compare blocked atomic commitment with a compensating workflow.');},foot:'Protocol sketches, not a complete 2PC or saga implementation. A payment timeout always needs outcome reconciliation.'});

labs.evolution=()=>({title:'Expand, migrate, contract',state:{stage:0,old:40},controls:[R('old','Old-version clients (%)',0,100,10),B('step','Next migration phase')],actions:{step:s=>s.stage=Math.min(4,s.stage+1)},render:s=>{
 const phases=['Old schema','Expand: add new field','Backfill + compare','Switch reads','Contract: remove old'];const broken=s.stage===4&&s.old>0;return flow(phases.map((x,i)=>[`${i+1}`,x,i===s.stage?'green':'']))+bars(['Old clients','New clients'],[s.old,100-s.old],100,['var(--orange)','var(--blue)'])+note(broken?`${s.old}% of clients still require the removed field. Contracting now breaks compatibility and may make rollback impossible.`:s.stage===4?'No old clients remain in this model. Also confirm delayed consumers, backfill correctness, and rollback requirements before removal.':'Progress through the phases while keeping both reader generations compatible. Treat the backfill as a throttled production workload.',broken);},foot:'Client percentages are illustrative. Compatibility also includes writers, consumers, and recovery tooling.'});

labs.placement=()=>({title:'Add a shard without moving everything',state:{n:4,method:'Rendezvous'},controls:[R('n','Current shard count',2,8),C('method','Placement',['Rendezvous','Modulo'])],render:s=>{
 const m=s.method.toLowerCase(),before=[],after=[];let moved=0;for(let i=0;i<120;i++){before.push(placement(`key-${i}`,s.n,m));after.push(placement(`key-${i}`,s.n+1,m));if(before[i]!==after[i])moved++;}const load=Array(s.n+1).fill(0);after.forEach(i=>load[i]++);return `<div class="ds-key-grid">${after.map((owner,i)=>`<span class="${before[i]!==owner?'moved':''}" title="Key ${i}: shard ${before[i]+1} to ${owner+1}">${owner+1}</span>`).join('')}</div>`+bars(load.map((_,i)=>`S${i+1}`),load)+stats(['Nodes before / after',`${s.n} / ${s.n+1}`],['Keys moved',`${moved} / 120`],['Sample moved',`${fmt(moved/120*100)}%`])+note('Highlighted keys changed owner. Rendezvous compares per-node scores; adding a node only moves keys whose new highest score belongs to it.');},foot:'Deterministic sample of 120 keys, unweighted nodes. Small samples need not be perfectly balanced.'});

labs.skew=()=>({title:'Find the hot shard',state:{n:4,hot:60,salted:false},controls:[R('n','Shards',2,8),R('hot','Traffic to one logical key (%)',0,90,5),T('salted','Split hot key into subkeys')],render:s=>{
 const load=shardLoads(s.n,s.hot,s.salted);return bars(load.map((_,i)=>`Shard ${i+1}`),load,100)+stats(['Busiest shard',`${fmt(Math.max(...load),1)}%`],['Ideal mean',`${fmt(100/s.n,1)}%`],['Reads for split key',s.salted?`${s.n} subkeys`:'1 key'])+note(s.salted?'The toy distributes the hot key evenly, at the cost of merging subkeys on reads. This is only valid if the operation can be split safely.':'Add more shards. The single hot key stays together, so its share does not disappear.');},foot:'Uniform background traffic plus one hot logical key. Subkey writes are assumed evenly distributed.'});

labs.caching=()=>({title:'Expire a popular cache entry',state:{readers:100,policy:'Plain cache-aside',expired:true},controls:[R('readers','Concurrent readers',10,1000,10),C('policy','Miss handling',['Plain cache-aside','Single-flight','Stale while revalidate']),T('expired','Entry expired')],render:s=>{
 const calls=s.expired?(s.policy==='Plain cache-aside'?s.readers:1):0;return flow([['Readers',s.readers,'blue'],['Cache',s.expired?'expired':'hit'],['Database',`${calls} refresh reads`,'purple']])+stats(['Backend calls',calls],['Wait for refresh',!s.expired||s.policy==='Stale while revalidate'?'No':'Yes'],['Stale answer possible',s.expired&&s.policy==='Stale while revalidate'?'Yes':'No*'])+note(s.policy==='Stale while revalidate'?'Readers receive the older value while one refresh runs. Only use this when stale data is acceptable.':'Coalescing suppresses duplicate work for this key. A fleet-wide cache outage still needs admission control and backend headroom.');},foot:'Simultaneous readers of one key, one coalescing scope. *Other invalidation races can still create stale data.'});

labs.regions=()=>({title:'Pay for distant coordination',state:{wan:90,policy:'Local async',failed:false},controls:[R('wan','WAN round trip (ms)',20,250,10),C('policy','Write acknowledgment',['Local async','Remote durable ack']),T('failed','Home region lost before async copy')],render:s=>{
 const sync=s.policy==='Remote durable ack';return flow([['Home region','local commit · 5 ms'],['WAN',`${s.wan} ms RTT`,''],['Remote region',sync?'durable before ack':'catches up later','blue']])+stats(['Toy ack latency',`${5+(sync?s.wan:0)} ms`],['Acknowledged copy outside home',sync?'Yes':'Not guaranteed'],['Latest acknowledged write',s.failed&&!sync?'May be lost':'Retained*'])+note(s.failed&&!sync?'A locally acknowledged write can disappear with its only durable region before async replication completes.':'Choose the durability promise, then budget for the network and define safe failover authority.');},foot:'Single synchronous WAN round trip, no processing overlap. *Assumes the remote durable copy remains healthy.'});

labs.delivery=()=>({title:'Crash after the effect, before the acknowledgment',state:{dedupe:true,total:0,seen:[],duplicate:false,attempts:0},controls:[T('dedupe','Atomic inbox + effect'),B('deliver','Deliver payment-42 again')],actions:{deliver:s=>{Object.assign(s,applyDelivery(s,'payment-42',10,s.dedupe));s.attempts++;}},render:s=>flow([['Broker','payment-42','blue'],['Worker',s.duplicate?'duplicate suppressed':'apply €10'],['Effect store',`€${s.total}`,'purple']])+chips(Array.from({length:Math.min(s.attempts,12)},()=> 'id:42'))+stats(['Delivery attempts',s.attempts],['Business total',`€${s.total}`],['Last attempt',s.duplicate?'Deduplicated':'Applied / pending'])+note(s.dedupe?'Repeated delivery with the same ID changes the balance once, provided the inbox record and effect commit atomically.':'Every retry adds another €10. The broker cannot undo a duplicated business effect.',!s.dedupe&&s.attempts>1),foot:'One event with a €10 effect. Reset before comparing policies; deduplication is modeled as atomic with the effect.'});

labs.outbox=()=>({title:'Find the dual-write gap',state:{mode:'Transactional outbox',crash:'After database commit'},controls:[C('mode','Producer design',['Independent writes','Transactional outbox']),C('crash','Crash point',['Before database commit','After database commit','After publish before relay ack'])],render:s=>{
 const committed=s.crash!=='Before database commit',outbox=s.mode==='Transactional outbox',published=s.crash==='After publish before relay ack';return flow([['Database',committed?'order committed':'no committed order'],['Outbox',outbox&&committed?'event durable':'no durable handoff',outbox?'green':''],['Broker',published?'event delivered':outbox&&committed?'relay will retry':'no event','blue']])+stats(['Order survives',committed?'Yes':'No'],['Event recoverable',committed?(outbox||published?'Yes':'NO'):'Not needed'],['Duplicates possible',published?'Yes':'On later relay retry'])+note(committed&&!outbox&&!published?'The order exists, but the event is gone. A separate broker call was never made.':published?'The event was published but progress was not recorded. A safe relay retries; the consumer must tolerate duplicates.':'An atomic local transaction keeps the order and its publish intent together. External delivery remains asynchronous.',committed&&!outbox&&!published);},foot:'Failure windows of one order event. Relay scheduling, cleanup, and reconciliation are simplified.'});

labs.streams=()=>({title:'Close a window, then deliver late data',state:{watermark:40,policy:'Update result',count:3},controls:[R('watermark','Watermark (event-time seconds)',0,90,5),C('policy','Late event policy',['Update result','Side output','Drop with metric']),B('arrive','Deliver next event')],actions:{arrive:s=>s.count=Math.min(6,s.count+1)},render:s=>{
 const events=[12,28,67,19,55,80].slice(0,s.count),late=events.filter(t=>t<s.watermark),accepted=events.filter(t=>t<60&&(t>=s.watermark||s.policy==='Update result'));return `<div class="ds-window"><span>Window [0, 60) seconds</span><strong>${s.watermark>=60?'Closed by watermark':'Still open'}</strong></div>`+chips(events.map(t=>`${t}s${t<s.watermark?' · late':''}`))+bars(['In-window accepted','Late arrivals','Outside window'],[accepted.length,late.length,events.filter(t=>t>=60).length],6,['var(--green)','var(--orange)','var(--blue)'])+note(`${late.length} event(s) fall behind the selected watermark. ${s.policy==='Update result'?'This policy permits revisions for late in-window events.':s.policy==='Side output'?'Late events are quarantined for separate handling.':'Late events are excluded and counted for visibility.'}`);},foot:'Replay of six arrivals against one chosen watermark, not a production watermark algorithm. All events have unit value.'});

labs.workflows=()=>({title:'Produce, process, and recover',state:{arrival:100,capacity:80,limit:true,queue:0,time:0,rejected:0},controls:[R('arrival','Jobs arriving / second',0,200,10),R('capacity','Workers’ total jobs / second',10,200,10),T('limit','Bound queue at 500 jobs'),B('tick','Run 10 seconds')],actions:{tick:s=>{for(let i=0;i<10;i++){const next=Math.max(0,s.queue+s.arrival-s.capacity);s.rejected+=s.limit?Math.max(0,next-500):0;s.queue=s.limit?Math.min(500,next):next;s.time++;}}},render:s=>flow([['Producers',`${s.arrival}/s`,'blue'],['Queue',`${s.queue} jobs`],['Workers',`${s.capacity}/s`,'purple']])+stats(['Elapsed',`${s.time} s`],['Drain time if arrivals stop',`${fmt(s.queue/s.capacity,1)} s`],['Rejected admissions',s.rejected])+note(s.arrival>s.capacity?'Work accumulates until admission is limited. Increasing consumers helps only while downstream capacity also permits it.':'Capacity exceeds or matches new arrivals. Existing backlog drains only when spare processing capacity remains.'),foot:'Discrete one-second fluid model; equal-cost jobs. Queue length is bounded after service within each step.'});

labs.deadlines=()=>({title:'Spend one end-to-end budget',state:{budget:300,queue:100,work:350,propagate:true},controls:[R('budget','Caller budget (ms)',100,1000,50),R('queue','Already spent (ms)',0,300,25),R('work','Downstream work (ms)',50,800,50),T('propagate','Propagate remaining deadline')],render:s=>{
 const remaining=Math.max(0,s.budget-s.queue),spent=s.propagate?Math.min(remaining,s.work):s.work,waste=Math.max(0,s.queue+spent-s.budget);return timeline([['Before call',0,s.queue,'var(--blue)'],['Downstream',s.queue,spent]],1200)+stats(['Remaining at call',`${remaining} ms`],['Useful completion',s.work<=remaining?'Within budget':'Cannot finish'],['Work after caller deadline',`${waste} ms`])+note(s.propagate?'This idealized cooperative callee stops when the remaining budget is exhausted. It may still have committed a side effect before cancellation.':'The independent timeout lets downstream work continue after the caller no longer wants the answer.',!s.propagate&&waste>0);},foot:'Cooperative cancellation is assumed. Real cancellation propagation and cleanup are not instantaneous.'});

labs.retries=()=>({title:'Retry amplification and synchronized waves',state:{layers:3,attempts:3,clients:30,jitter:true},controls:[R('layers','Retrying layers',1,5),R('attempts','Total attempts per layer',1,4),R('clients','Clients failing together',10,100,10),T('jitter','Full jitter')],render:s=>{
 const bins=retrySchedule(s.clients,4,s.jitter);return stats(['Worst-case leaf attempts',s.attempts**s.layers],['Top-level user action','1'],['Peak retry bucket',Math.max(...bins)])+bars(bins.map((_,i)=>`${i}`),bins)+note('Bars compare four retry rounds for the same client group. Jitter spreads arrivals; it does not reduce the number of attempts. Retry budgets and a single retry owner bound the load.');},foot:'Four backoff windows of 1, 2, 4, 8 units; rounds are overlaid by delay bucket. Deterministic jitter sample, not a wall-clock timeline.'});

labs.overload=()=>({title:'Bound the burst with a token bucket',state:{capacity:50,refill:10,requests:30,tokens:50,accepted:0,rejected:0,ticks:0},controls:[R('capacity','Bucket capacity',10,100,10),R('refill','Refill tokens / second',1,30),R('requests','Requests this second',5,100,5),B('tick','Advance one second')],actions:{tick:s=>{const r=bucketStep(s.tokens,s.capacity,s.refill,s.requests);s.tokens=r.tokens;s.accepted=r.accepted;s.rejected=r.rejected;s.ticks++;}},onChange:(s,key)=>{if(key==='capacity')s.tokens=Math.min(s.tokens,s.capacity);},render:s=>{
 return `<div class="ds-bucket"><div style="height:${s.tokens/s.capacity*100}%"></div><strong>${s.tokens} / ${s.capacity}</strong><span>available tokens</span></div>`+stats(['Last accepted',s.accepted],['Last rejected',s.rejected],['Sustained refill',`${s.refill}/s`])+note('A full bucket admits an initial burst. Continued arrivals above the refill rate are rejected. This does not cap concurrent requests if each accepted request becomes slow.');},foot:'One token per request; refill occurs before admission. In-memory single limiter with no distributed races.'});

labs.contracts=()=>({title:'Trace identity to authorization',state:{authenticated:true,tenant:'Tenant B',check:true},controls:[T('authenticated','Caller authenticated as tenant A'),C('tenant','Requested object belongs to',['Tenant A','Tenant B']),T('check','Enforce object-level authorization')],render:s=>{
 const allowed=s.authenticated&&(!s.check||s.tenant==='Tenant A'),leak=allowed&&s.tenant==='Tenant B';return flow([['Caller',s.authenticated?'principal: tenant A':'anonymous','blue'],['Object',s.tenant,'purple'],['Decision',allowed?'ALLOW':'DENY',leak?'purple':'green']])+note(leak?'The caller is authenticated but reads another tenant’s resource. TLS and a valid session did not enforce object ownership.':!s.authenticated?'Authentication fails before this protected object is returned.':'The authorization decision checks the requested object’s tenant, not just whether the caller has a session.',leak);},foot:'Simplified tenant-equality policy. Real policies can include roles, sharing, attributes, and delegated scopes.'});

labs.slos=()=>({title:'Measure error-budget burn',state:{slo:99.9,errors:1,minutes:60},controls:[R('slo','30-day success SLO (%)',99,99.99,.01),R('errors','Observed error rate (%)',0,10,.1),R('minutes','Incident duration (minutes)',5,360,5)],render:s=>{
 const b=burnRate(s.slo,s.errors,s.minutes);return stats(['Burn rate',`${fmt(b.rate,1)}×`],['Monthly budget consumed',`${fmt(b.spent,2)}%`],['Time to exhaust at this rate',Number.isFinite(b.hours)?`${fmt(b.hours,1)} h`:'Never'])+`<div class="ds-budget"><i style="width:${Math.min(100,b.spent)}%"></i></div><p class="caption">${fmt(Math.max(0,100-b.spent),2)}% of an initially full error budget remains</p>`+note(b.rate>1?'The service is spending faster than the long-run allowance. Decide whether the rate and duration justify immediate mitigation.':'Current consumption is at or below the sustainable rate. The full SLO window and traffic distribution still matter.');},foot:'Request-based SLO. Uniform traffic is assumed when converting incident duration into monthly budget consumption.'});

labs.observability=()=>({title:'Find the bottleneck in a trace',state:{cause:'Database lock',queue:180},controls:[C('cause','Injected failure',['Database lock','Downstream timeout','Healthy']),R('queue','Wait duration (ms)',20,400,20)],render:s=>{
 const wait=s.cause==='Healthy'?10:s.queue;const spans=[['Gateway',0,20],['Application',20,30],['DB query',50,s.cause==='Database lock'?wait:25,'var(--orange)'],['External API',75,s.cause==='Downstream timeout'?wait:30,'var(--blue)']];return timeline(spans,500)+stats(['Application CPU','25%'],['DB waiters',s.cause==='Database lock'?42:2],['External errors',s.cause==='Downstream timeout'?'12%':'0.1%'])+note(s.cause==='Database lock'?'Inspect blocking transactions and lock duration. Adding app workers can increase lock contention.':s.cause==='Downstream timeout'?'Bound concurrency, check downstream health, and inspect deadlines and retry volume. Avoid amplifying failures.':'The trace has short dependencies in this example. Production conclusions need representative traces and aggregate metrics.');},foot:'Synthetic trace with overlapping DB/API spans. CPU and error figures are illustrative, not measured telemetry.'});

labs.releases=()=>({title:'Expose a small cohort',state:{canary:5,errors:60,rollback:false},controls:[R('canary','Traffic on canary (%)',1,100),R('errors','Canary error rate (%)',0,100,5),T('rollback','Roll traffic back')],render:s=>{
 const exposure=s.rollback?0:s.canary,overall=exposure/100*s.errors+(1-exposure/100)*.1;return bars(['Baseline error %','Canary error %','Overall error %'],[.1,s.errors,overall],100,['var(--blue)','var(--orange)','var(--green)'])+stats(['Exposed traffic',`${exposure}%`],['Global error rate',`${fmt(overall,2)}%`],['Canary failure rate',`${s.errors}%`])+note(s.rollback?'Traffic returns to the baseline. This does not undo corrupted data or external side effects already produced.':'The aggregate dilutes the canary’s failures. Evaluate the exposed cohort with enough requests and a matching baseline.');},foot:'Uniform request cost, baseline errors fixed at 0.1%. No statistical significance claim is made.'});

labs.recovery=()=>({title:'Budget a restore',state:{backupAge:240,logLag:5,restoreMinutes:45,replayMinutes:15,pitr:true},controls:[R('backupAge','Base backup age (minutes)',60,1440,60),R('logLag','Archived-log lag (minutes)',0,60,5),R('restoreMinutes','Restore duration (minutes)',10,180,10),T('pitr','Usable continuous log archive')],render:s=>{
 const r=recovery(s);return flow([['Base backup',`${s.backupAge} min old`,'blue'],['Log archive',s.pitr?`${s.logLag} min behind`:'unavailable','purple'],['Recoverable state',`${r.rpo} min of exposure`]])+stats(['Toy data-loss window',`${r.rpo} min`],['Restore + replay',`${r.rto} min`],['Replay duration',`${s.pitr?s.replayMinutes:0} min`])+note('This only measures the data and restore stages. Add detection, decisions, capacity provisioning, validation, and cutover to estimate the full recovery time.');},foot:'Assumes an intact base backup and a complete log chain when enabled. Corruption or missing keys invalidate the estimate.'});

labs.sizing=()=>({title:'Convert usage into capacity',state:{users:1,actions:10,ratio:20,bytes:1000,peak:5,days:30},controls:[R('users','Daily active users (millions)',1,20),R('actions','Writes per user per day',1,100),R('ratio','Reads per write',1,100),R('peak','Peak / average traffic',1,20),R('days','Retention (days)',1,365)],render:s=>{
 const e=estimate(s.users*1e6,s.actions,s.ratio,s.bytes,s.peak,s.days);return stats(['Average writes / sec',fmt(e.writes)],['Peak total requests / sec',fmt(e.peak)],['Raw retained data',`${fmt(e.storage/1e12,2)} TB`])+flow([['Usage',`${s.users}M people`,'blue'],['Read / write',`${s.ratio}:1`],['Raw read egress',`${fmt(e.egress/1e9)} GB/day`,'purple']])+note('Add replicas, indexes, caches, retries, fan-out, and operational headroom separately. Egress assumes every read returns the full 1 KB record.');},foot:'Decimal units; 1 KB per write/read. Daily average is divided by 86,400 seconds. No compression or overhead included.'});

const blueprints={
 'Feed':{nodes:['Post API','Durable posts + outbox','Fan-out workers','Inbox cache + ranked read'],invariant:'Do not lose acknowledged posts; define acceptable feed delay.',key:'recipient ID / author ID',fault:'A celebrity creates extreme fan-out.',trade:'Hybrid fan-out: precompute ordinary authors; assemble high-fanout authors on read.'},
 'Chat':{nodes:['WebSocket gateway','Conversation owner','Durable partitioned log','Online delivery + offline replay'],invariant:'Stable message IDs and per-conversation ordering.',key:'conversation ID',fault:'A gateway dies after persistence but before delivery.',trade:'Reconnect with a cursor, replay durable history, and deduplicate client-visible messages.'},
 'Payments':{nodes:['Payment API + idempotency','Transactional ledger','Outbox / provider worker','Reconciliation + audit'],invariant:'Balance rules, one logical charge per operation, and an auditable history.',key:'account / transfer ID',fault:'The provider charges the card but its response is lost.',trade:'Reuse a durable operation key; query the provider and reconcile before issuing a new effect.'},
 'Media':{nodes:['Scoped upload URL','Object storage + checksum','Transcode queue + workers','Metadata / CDN / search index'],invariant:'Only authorized, validated objects become discoverable.',key:'object ID / tenant ID',fault:'Upload completes but metadata finalization fails.',trade:'Use idempotent finalization, reconciliation, and cleanup of orphaned multipart uploads.'}
};
labs.blueprints=()=>({title:'Inspect an architecture by its invariant',state:{system:'Feed',failure:false},controls:[C('system','System',['Feed','Chat','Payments','Media']),T('failure','Inject failure')],render:s=>{
 const b=blueprints[s.system];return flow(b.nodes)+table(['Design question','Choice'],[['Invariant',b.invariant],['Partition identity',b.key],['Failure to handle',b.fault]])+note(s.failure?b.trade:'Inject the failure. The important question is which durable record lets the system recover without inventing a second operation.',s.failure);},foot:'Architecture sketches for reasoning. Each omits many service-specific product, security, and deployment requirements.'});

labs.boundaries=()=>({title:'Keep tenant identity through the cache',state:{tenant:'Tenant B',scoped:true,authorized:false},controls:[C('tenant','Current caller',['Tenant A','Tenant B']),T('scoped','Include tenant in cache key'),T('authorized','Caller granted access to tenant A object')],render:s=>{
 const owns=s.tenant==='Tenant A',allowed=owns||s.authorized,key=s.scoped?`${s.tenant}:object-7`:'object-7',leak=!owns&&!s.scoped&&!s.authorized;return flow([['Caller',s.tenant,'blue'],['Cache lookup',key,'purple'],['Cached A payload',leak?'LEAK if cache bypasses policy':allowed?'authorized route':'deny / tenant-local miss',leak?'purple':'green']])+note(leak?'An unscoped cache hit can return tenant A’s data before the authoritative access check. Scope the key and enforce the object’s access policy.':allowed?'The requested access is permitted in this toy policy. Cache scoping still matters when identifiers overlap.':'This caller lacks access to tenant A’s object. A tenant-specific cache miss must not bypass the authoritative authorization check.',leak&&!allowed);},foot:'Cache preloaded with tenant A’s object-7. Demonstrates an unsafe cache-before-authorization design, not a recommended pipeline.'});

const decisions={
 'Start simply':['Modular application','One transactional database','Explicit module ownership','Measure traffic and team friction'],
 'Isolate a bottleneck':['Modular core','Queue / stable contract','One independently scaled worker','Owner, SLO, and recovery path'],
 'Split by ownership':['Service boundary','Owned data and API','Async integration + reconciliation','Independent on-call and migration plan']
};
labs.decisions=()=>({title:'Record why a boundary exists',state:{choice:'Start simply',evidence:'No measured constraint'},controls:[C('choice','Proposed evolution',Object.keys(decisions)),C('evidence','Evidence',['No measured constraint','Measured independent scaling need','Independent ownership and release need'])],render:s=>{
 const justified=s.choice==='Start simply'||s.choice==='Isolate a bottleneck'&&s.evidence==='Measured independent scaling need'||s.choice==='Split by ownership'&&s.evidence==='Independent ownership and release need';return flow(decisions[s.choice])+table(['Decision record','Make explicit'],[['Requirement','What invariant or constraint must improve?'],['Cost','Latency, coordination, operations, and recovery'],['Validation','Load / failure / compatibility experiment'],['Revisit trigger','A measured limit, not a calendar date']])+note(justified?'The evidence can support this direction. Validate the assumptions, plan migration, and assign operational ownership.':'The selected evidence does not yet justify this boundary. Find a measurable need or choose a simpler reversible starting point.',!justified);},foot:'A reasoning aid, not an architecture score. Context can justify choices beyond these three examples.'});

export const mountLab=(element,id)=>mountExperiment(element,labs[id]());
export const labIds=()=>Object.keys(labs);
export const createLab=id=>labs[id]();
